async function loadDashboard(timeoutMs = 5000) {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  const getJson = async url => { const r = await fetch(url, { signal: controller.signal }); if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); };
  try {
    const [profile, orders] = await Promise.all([getJson('/api/profile'), getJson('/api/orders')]);
    return { profile, orders };
  } finally { clearTimeout(timer); }
}
